E" transform="translate(24 147.6) scale(0.9)"/><use href="#pa-firC" transform="translate(44 144.9) scale(0.6)"/><use href="#pa-firE" transform="translate(64 142.5) scale(1)"/><use href="#pa-firC" transform="translate(84 140.3) scale(0.55)"/><use href="#pa-firE" transform="translate(190 133.9) scale(0.8)"/><use href="#pa-firE" transform="translate(208 132.9) scale(1)"/><use href="#pa-firC" transform="translate(226 132.9) scale(0.55)"/><use href="#pa-firE" transform="translate(300 132.0) scale(0.85)"/><use href="#pa-firC" transform="translate(452 140.0) scale(0.6)"/><use href="#pa-firE" transform="translate(466 142.5) scale(0.9)"/><use href="#pa-firB" transform="translate(604 238) scale(0.7)"/><use href="#pa-firA" transform="translate(624 238) scale(0.8)"/><use href="#pa-firD" transform="translate(646 238) scale(0.75)"/><use href="#pa-firB" transform="translate(668 238) scale(0.75)"/><use href="#pa-firC" transform="translate(690 238) scale(0.85)"/><use href="#pa-firB" transform="translate(1150 238) scale(0.9)"/><use href="#pa-firD" transform="translate(1174 238) scale(1.05)"/><use href="#pa-firA" transform="translate(1200 238) scale(0.95)"/><use href="#pa-firB" transform="translate(1226 238) scale(0.9)"/><use href="#pa-firC" transform="translate(1250 238) scale(1)"/><use href="#pa-chalet" transform="translate(1172 84) scale(0.72)" stroke="var(--pa-hole,#F6F5F1)" stroke-width="4.17" stroke-linejoin="round"/><use href="#pa-chalet" transform="translate(1172 84) scale(0.72)"/>`
const HEART = 'm0-21.5c-1.1 0-3.2-2.8-3.6-3.8-.5-1 .2-2.5.6-3 .3-.6 1.4-.6 1.9-.4 .4.1.8 1.5 1.1 1.5 .3 0 .7-1.4 1.1-1.5 .5-.2 1.6-.2 1.9.4 .4.5 1.1 2 .6 3-.4 1-2.5 3.8-3.6 3.8z'
const at = walker(PATH)
const back = (s: number) => at(s - 24)
const clamp = (p: number) => Math.max(0, Math.min(4, Math.round(p)))
// arc length of a position between stations, for a herd that glides
const along = (p: number) => {
  const i = Math.max(0, Math.min(4, p))
  const a = Math.min(3, Math.floor(i))
  return STATION_S[a] + (STATION_S[a + 1] - STATION_S[a]) * (i - a)
}

const pos = ref(STATION_S[clamp(props.progress)])
let raf = 0
watch(
  () => props.progress,
  (p) => {
    const target = STATION_S[clamp(p)]
    cancelAnimationFrame(raf)
    const still = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches
    if (!props.animate || still) { pos.value = target; return }
    const from = pos.value, dur = 900, t0 = performance.now()
    const step = (now: number) => {
      const u = Math.min(1, (now - t0) / dur)
      pos.value = from + (target - from) * (u < 0.5 ? 2 * u * u : 1 - Math.pow(-2 * u + 2, 2) / 2)
      if (u < 1) raf = requestAnimationFrame(step)
    }
    raf = requestAnimationFrame(step)
  },
)
onBeforeUnmount(() => cancelAnimationFrame(raf))

// lead armailli, lead cow and two followers, placed behind the station point
const GROUP = [
  { n: 'manLead', d: -10, w: 6 },
  { n: 'cowLead', d: -28, w: 52 },
  { n: 'cowB1', d: -86, w: 52 },
  { n: 'cowS3', d: -142, w: 52 },
]
const figures = computed(() =>
  GROUP.map((g) => {
    const s = (props.at !== undefined ? along(props.at) : pos.value) + g.d
    const a = at(s), b = back(s)
    const tilt = (Math.atan2(a.y - b.y, a.x - b.x) * 180) / Math.PI * 0.8
    return { href: '#pa-' + g.n, t: `translate(${a.x.toFixed(1)} ${a.y.toFixed(1)}) rotate(${tilt.toFixed(1)}) translate(${-g.w} 0) scale(0.5)` }
  }),
)
const stations = POYA_STATIONS
</script>

<template>
  <div class="poya-path">
    <svg viewBox="0 0 1280 260" :style="colours(ink, paper)" role="img" aria-label="Roadmap drawn as the climb to the alp, with five stations">
      <defs v-html="POYA_SYMBOLS" />
      <g v-html="SCENE" />
      <g v-for="(p, i) in stations" :key="i" :transform="`translate(${p.x} ${p.y + 0.5})`">
        <use href="#pa-post" />
        <path v-if="mark !== undefined ? i === mark : i <= progress" fill="var(--pa-mark, var(--pa-red))" :d="HEART" />
      </g>
      <use v-for="(f, i) in figures" :key="'f' + i" :href="f.href" :transform="f.t" />
    </svg>
    <div v-for="(p, i) in stations" :key="'l' + i" class="station" :style="{ left: p.left + '%', top: p.top + '%' }">
      <slot name="station" :index="i" :reached="i <= progress" />
    </div>
  </div>
</template>

